private TimeSegment calculateTimeSegment(long start, long end) {
    // Calculate the start and end of each segment
    long segmentStart = calculateStart(start, end);
    long segmentEnd = calculateEnd(start, end);
    // Check if the segment is valid
    if (segmentStart >= segmentEnd) {
        return null;
    }
    return new TimeSegment(segmentStart, segmentEnd);
}

