public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("CharSequence cannot be null");
    }
    if (index < 0 || len <= 0) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int byteSize = 0;
    while (len > 0) {
        char c = str.charAt(index++);
        if (c <= 0x7F) {
            byteSize += 1;
            len--;
        } else if (c <= 0x7FF) {
            byteSize += 2;
            len--;
        } else if (c <= 0xFFFF) {
            byteSize += 3;
            len--;
        } else {
            byteSize += 4;
            len--;
        }
    }
    return byteSize;
}

