    if (firstByte == -1) {
        throw new EOFException("Reached the end of the stream before a varint was encoded.");
    }

    boolean isNegative = (firstByte & 0x80) != 0;
    value |= (firstByte & 0x7F);

    if ((firstByte & 0x80) == 0) {
        return value;
    }

    int shift = 7;
    int byteIndex = 1;

    while ((firstByte & 0x80) != 0) {
        firstByte = in.read();
        if (firstByte == -1) {
            throw new EOFException("Reached the end of the stream before a varint was encoded.");
        }

        value |= ((firstByte & 0x7F) << shift);
        shift += 7;
        byteIndex++;
    }

    return(isNegative) ? ~value : value;
}

