public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) return 2;

    boolean isPrime = false;
    for (int prime = 3; prime <= Math.sqrt(desiredCapacity); prime += 2) {
        if (desiredCapacity % prime == 0) {
            isPrime = false;
            break;
        }
    }

    if (isPrime) {
        // Check if the prime number is within the desired range or not
        if (desiredCapacity >= 1000 && Math.abs(desiredCapacity - prime) <= desiredCapacity / 10) {
            return prime;
        }
    }

    return prime + 2; // Return the next Euler's number-based prime number
}

