    if (node == null) {
        return false;
    }

    // Set the previous node's next pointer to the node after the one to be removed
    if (node.previous != null) {
        node.previous.next = node.next;
    } else {
        // If the node is the first node, update the head reference
        head = node.next;
    }

    // Set the next node's previous pointer to the node before the one to be removed
    if (node.next != null) {
        node.next.previous = node.previous;
    } else {
        // If the node is the last node, update the tail reference
        tail = node.previous;
    }

    // Decrement the list size
    size--;

    return true;
}

