public static String base64Decode(final String s) {
    int sBytesLength = s.length();
    if (sBytesLength % 4 != 0) {
        throw new IllegalArgumentException("Invalid length of Base64 string: " + sBytesLength);
    }
    byte[] decodedBytes = new byte[sBytesLength / 4]; // Each character in Base64 is represent by 4 bits, 4 * 4 / 8 = 1 byte
    for (int i = 0; i < sBytesLength; i += 4) {
        int char1 = base64CharToDigit(s.charAt(i));
        int char2 = base64CharToDigit(s.charAt(i + 1));
        int char3 = base64CharToDigit(s.charAt(i + 2));
        int char4 = base64CharToDigit(s.charAt(i + 3));
        int byte1 = (char1 << 2) + (char2 >> 4);
        int byte2 = ((char2 & 15) << 4) + (char3 >> 2);
        int byte3 = ((char3 & 3) << 6) + char4;
        decodedBytes[i / 4] = (byte) (byte1 | byte2 | byte3);
    }
    return new String(decodedBytes);
}

