public List<Integer> computeLowerBounds(List<K> keys) {
    // Sort the keys because we need to find the lower bound for each key
    Collections.sort(keys);

    List<Integer> lowerBounds = new ArrayList<>();
    Integer currentMin = null;

    // Iterate through each key and find its lower bound
    for (K key : keys) {
        // If it's the first key, set its lower bound to 0
        if (currentMin == null) {
            currentMin = 0;
        } else {
            // Otherwise, set it to the higher value between the current minimum and the current key's index
            currentMin = Math.max(currentMin, keys.indexOf(key)-1);
        }
        lowerBounds.add(currentMin);
    }

    return lowerBounds;
}

