public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // read timestamps from conf or file
    Set<Long> timestamps = new TreeSet<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        timestamps.add(timeRange.startTimestamp);
        timestamps.add(timeRange.endTimestamp);
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (Scanner scanner = new Scanner(file)) {
        scanner.useDelimiter("[\t,]");
        while (scanner.hasNext()) {
            String timeStr = scanner.next();
            String threadStr = scanner.next();
            String.Collectors = scanner.next();
            String durationStr = scanner.next();
            String[] threadStack = scanner.nextLine().split("\t");

            Long timestamp = Long.parseLong(timeStr);
            if (timestamps.contains(timestamp)) {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp);
                snapshot.setThread(threadStr);
                snapshot.setCollectors(collectors);
                snapshot.setDuration(Long.parseLong(durationStr));
                snapshot.setThreadStack(threadStack);

                snapshots.add(snapshot);
            }
        }
    }

    return snapshots;
}
